"""Checks rack outputs generated by the native regression requests."""
import hashlib
import json
import math
from pathlib import Path
import re
import unittest

ROOT = Path(__file__).resolve().parents[1]


class RackDrawingTests(unittest.TestCase):
    def check_case(self, key, declared):
        root = ROOT / 'artifacts/v1.3.5'
        result = root / ('final-' + key + '-result.json')
        if not result.exists() or not result.stat().st_size:
            self.skipTest('native ' + key + ' rack run not completed')
        j = json.loads(result.read_text(encoding='utf-8-sig'))['Jobs'][0]
        self.assertIsNone(j['Error'])
        self.assertEqual(j['GeneratorVersion'], '1.3.5')
        self.assertEqual(j['Status'], 'review_required')
        self.assertEqual(j['AutoDimensions'], [])
        self.assertEqual(len(j['Dimensions']), 3)
        self.assertEqual(sorted(round(d['ValueSI'] * 1000, 5) for d in j['Dimensions']), [50, 50, 998])
        self.assertEqual(j['ChamferSilhouetteScans'], 0)
        rack = j['Rack']
        self.assertTrue(rack['Reopened'])
        self.assertEqual(rack['HoleTableAssociativity'], 'snapshot_at_generation')
        self.assertTrue(all(t['Reopened'] for t in rack['Tables']))
        self.assertAlmostEqual(rack['Geometry']['MeasuredPitchMm'], 5 * math.pi, 5)
        self.assertEqual(len(rack['Holes']), 6)
        self.assertEqual([round(h['FromStartMm'], 5) for h in rack['Holes']], [49, 229, 409, 589, 769, 949])
        self.assertEqual([round(h['HeightDatumMm'], 5) for h in rack['Holes']], [16] * 6)
        self.assertEqual([h['Specification'] for h in rack['Holes']], ['Φ12贯通；沉孔Φ18深22'] * 6)
        self.assertTrue(all(h['Entities'] for h in rack['Holes']))
        if declared:
            self.assertEqual(j['Recognition']['PartClass'], 'rack')
            self.assertEqual(rack['Parameters']['Module'], '5')
            self.assertEqual(rack['Parameters']['PressureAngle'], '20')
            self.assertEqual(rack['Sources']['Module'], 'request.RackParameters')
        else:
            self.assertEqual(j['Recognition']['PartClass'], 'rack_candidate')
            self.assertNotIn('Module', rack['Parameters'])
            self.assertNotIn('PressureAngle', rack['Parameters'])
        for field in ('Drawing', 'Pdf', 'Dxf'):
            self.assertGreater(Path(j[field]).stat().st_size, 0)
        audit = json.loads(Path(j['PdfReview']).read_text(encoding='utf-8-sig'))
        self.assertTrue(audit['all_dimensions_matched'])
        import fitz
        with fitz.open(j['Pdf']) as pdf:
            text = re.sub(r'\s+', '', ''.join(page.get_text() for page in pdf))
        self.assertIn('齿条参数', text)
        self.assertIn('沉孔Φ18深22', text)
        self.assertIn('轴测比例', text)
        import ezdxf
        dxf = ezdxf.readfile(j['Dxf'])
        self.assertFalse(dxf.audit().errors)
        texts = ''.join(e.plain_text() if e.dxftype() == 'MTEXT' else e.dxf.text
                        for block in dxf.blocks for e in block if e.dxftype() in ('TEXT', 'MTEXT'))
        self.assertIn('齿条参数', texts)
        self.assertIn('沉孔Φ18深22', re.sub(r'\s+', '', texts))
        self.assertEqual(len(dxf.modelspace().query('DIMENSION')), 3)
        self.assertEqual(hashlib.sha256(Path(j['Model']).read_bytes()).hexdigest(), (root / 'source.sha256').read_text().strip())

    def test_detect_without_guessing_parameters(self):
        self.check_case('default', False)

    def test_explicit_manufacturing_parameters(self):
        self.check_case('specified', True)


if __name__ == '__main__':
    unittest.main()
